{{--
    Percorso di navigazione della pagina corrente.

    Le voci vengono risolte in automatico da App\Services\Breadcrumbs (mappa in config/seo.php
    + eventuali voci aggiunte dal controller), per cui il componente si usa senza parametri:

        <x-breadcrumbs />

    Nelle pagine in cui il titolo della pagina coincide con l'ultima voce del percorso
    (es. "Azienda", "News", ...) si può evitare la ripetizione stampando il titolo
    direttamente come ultima voce, passando il tag da usare:

        <x-breadcrumbs current-tag="h1" />

    I dati strutturati "BreadcrumbList" sono stampati a parte dal layout base,
    quindi qui non serve markup microdata.
--}}
@props([
    // tag della voce corrente (l'ultima, non linkata)
    'currentTag' => 'span',
])

@php
    $items = app(App\Services\Breadcrumbs::class)->items();
@endphp

@if($items)
<nav class="breadcrumbs" aria-label="{{ __('global.breadcrumb') }}">
    <ol>
        @foreach ($items as $item)
        <li>
            @if($item['url'])
            <a href="{{ $item['url'] }}">{{ $item['name'] }}</a>
            @else
            <{{ $currentTag }} aria-current="page">{{ $item['name'] }}</{{ $currentTag }}>
            @endif
        </li>
        @endforeach
    </ol>
</nav>
@endif

