3	namespace App\Services;
4	
5	use Illuminate\Routing\Route;
6	use Illuminate\Support\Facades\Request;
7	
8	/**
9	 * Percorso di navigazione (breadcrumb) della pagina corrente.
10	 *
11	 * Le voci "statiche" vengono risolte in automatico dalla mappa in config/seo.php
12	 * in base alla route attiva, per cui le pagine fisse non richiedono alcun codice.
13	 * Le pagine di dettaglio (prodotto, news, progetto, ...) aggiungono le voci dinamiche
14	 * dal controller con push().
15	 *
16	 * La classe è registrata come singleton in AppServiceProvider, quindi le voci
17	 * aggiunte dal controller sono disponibili al layout e al componente x-breadcrumbs.
18	 *
19	 * Il percorso viene usato sia per l'output html sia per il blocco JSON-LD
20	 * "BreadcrumbList" (v. toJsonLd()).
21	 */
22	class Breadcrumbs
23	{
24	    /**
25	     * Voci aggiunte manualmente, accodate a quelle risolte dalla route.
26	     *
27	     * @var array<int, array{name: string, url: string|null}>
28	     */
29	    protected array $extra = [];
30	
31	    /**
32	     * Aggiunge una voce in coda al percorso.
33	     * L'url va omessa per la voce finale (la pagina corrente).
34	     */
35	    public function push(string $name, ?string $url = null): static
36	    {
37	        $name = trim($name);
38	
39	        if (strlen($name)) {
40	            $this->extra[] = ['name' => $name, 'url' => $url];
41	        }
42	
43	        return $this;
44	    }
45	
46	    /**
47	     * Percorso completo: home + voci della route + voci aggiunte dal controller.
48	     *
49	     * @return array<int, array{name: string, url: string|null}>
50	     */
51	    public function items(): array
52	    {
53	        $items = array_merge($this->routeItems(), $this->extra);
54	
55	        // solo la home: non c'è un percorso da mostrare (es. homepage)
56	        if (count($items) < 2) {
57	            return [];
58	        }
59	
60	        // l'ultima voce è la pagina corrente, non deve essere un link
61	        $items[count($items) - 1]['url'] = null;
62	
63	        return $items;
64	    }
65	
66	    public function isEmpty(): bool
67	    {
68	        return $this->items() === [];
69	    }
70	
71	    /**
72	     * Blocco JSON-LD "BreadcrumbList", o null se la pagina non ha un percorso.
73	     */
74	    public function toJsonLd(): ?array
75	    {
76	        $items = $this->items();
77	
78	        if (!$items) {
79	            return null;
80	        }
81	
82	        return [
83	            '@type'           => 'BreadcrumbList',
84	            '@id'             => Request::url().'#breadcrumb',
85	            'itemListElement' => array_map(function (array $item, int $index) {
86	                $element = [
87	                    '@type'    => 'ListItem',
88	                    'position' => $index + 1,
89	                    'name'     => $item['name'],
90	                ];
91	
92	                // la voce finale (pagina corrente) non espone l'url
93	                if ($item['url']) {
94	                    $element['item'] = url($item['url']);
95	                }
96	
97	                return $element;
98	            }, $items, array_keys($items)),
99	        ];
100	    }
101	
102	    /**
103	     * Voci ricavate dalla route attiva: home + catena definita in config/seo.php.
104	     *
105	     * @return array<int, array{name: string, url: string|null}>
106	     */
107	    protected function routeItems(): array
108	    {
109	        $items = [
110	            ['name' => __('global.home'), 'url' => route('homepage')],
111	        ];
112	
113	        $map = config('seo.breadcrumbs', []);
114	
115	        // risalgo la catena dei "parent" a partire dalla route corrente
116	        $chain = [];
117	        $code = $this->currentRouteCode();
118	        while ($code && isset($map[$code]) && !in_array($code, $chain, true)) {
119	            array_unshift($chain, $code);
120	            $code = $map[$code]['parent'] ?? null;
121	        }
122	
123	        foreach ($chain as $code) {
124	            // senza label la voce è dinamica: la aggiunge il controller con push()
125	            if (empty($map[$code]['label'])) {
126	                continue;
127	            }
128	
129	            // route() ritorna "#" se la url non è generabile (es. parametri mancanti)
130	            $url = route($code);
131	
132	            $items[] = [
133	                'name' => __($map[$code]['label']),
134	                'url'  => $url !== '#' ? $url : null,
135	            ];
136	        }
137	
138	        return $items;
139	    }
140	
141	    /**
142	     * Codice della route corrente, privo del suffisso di lingua
143	     * (v. App\Providers\ViewServiceProvider).
144	     */
145	    protected function currentRouteCode(): ?string
146	    {
147	        $route = Request::route();
148	
149	        if (!$route instanceof Route || !$route->getName()) {
150	            return null;
151	        }
152	
153	        return str_replace('_'.app()->getLocale(), '', $route->getName());
154	    }
155	}
