View::composer(['layouts.base', 'products.category', 'products.kaleido.components.menu-interno'], function ($view) {
    $view->menuCategories = Prodcat::roots()
        ->with([
            'children' => fn ($query) => $query->listByLang(app('LangManager')->idByPrefix(app()->getLocale()))
        ])
        ->listbyLang(app('LangManager')->idByPrefix(app()->getLocale()))
        ->get();
});

/**
 * Dati strutturati globali, presenti su ogni pagina:
 * Organization (sempre) + BreadcrumbList (se la pagina ha un percorso).
 * I dati strutturati specifici della pagina viaggiano invece
 * nella variabile "jsonLdContent", valorizzata dai controller.
 */
View::composer(['layouts.base'], function ($view) {
    $graph = [(new Organization())->toArray()];

    $breadcrumbs = app(Breadcrumbs::class)->toJsonLd();
    if ($breadcrumbs) {
        $graph[] = $breadcrumbs;
    }

    $view->jsonLdGlobal = [
        '@context' => 'https://schema.org',
        '@graph'   => $graph,
    ];
});

// conteggio favoriti per mostrare icona menu al load

