public function __construct()
{
    // request per minute
    $this->middleware('throttle:10,1')->except(['index', 'success', 'newsletterSuccess']);
}


public function index(LangManager $langManager)
{
    $hq = config('site.company.headquarter');
    $sr = config('site.company.showroom');

    $jsonLdContent = [
        '@context' => 'https://schema.org',
        '@graph'   => [
            [
                '@type'     => 'LocalBusiness',
                '@id'       => config('app.url') . '/#headquarter',
                'name'      => config('site.company.name'),
                'url'       => config('app.url'),
                'telephone' => $hq['phone'],
                'faxNumber' => $hq['fax'],
                'email'     => $hq['email'],
                'address'   => [
                    '@type'           => 'PostalAddress',
                    'streetAddress'   => $hq['street_address'],
                    'postalCode'      => $hq['postal_code'],
                    'addressLocality' => $hq['city'],
                    'addressRegion'   => $hq['province'],
                    'addressCountry'  => $hq['country'],
                ],
            ],
            [
                '@type'     => 'LocalBusiness',
                '@id'       => config('app.url') . '/#showroom',
                'name'      => $sr['name'],
                'url'       => config('app.url'),
                'telephone' => $sr['phone'],
                'email'     => $sr['email'],
                'address'   => [
                    '@type'           => 'PostalAddress',
                    'streetAddress'   => $sr['street_address'],
                    'postalCode'      => $sr['postal_code'],
                    'addressLocality' => $sr['city'],
                    'addressCountry'  => $sr['country'],
                ],
            ],
        ],
    ];

    return view('contatti.index', compact('jsonLdContent'));
}

